DROP TRIGGER booking_monthly_contract_identity;
CREATE TRIGGER booking_monthly_contract_identity BEFORE UPDATE ON booking_monthly_contracts WHEN NEW.id IS NOT OLD.id OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.account_id IS NOT OLD.account_id  OR NEW.friend_id IS NOT OLD.friend_id OR NEW.class_kind IS NOT OLD.class_kind OR NEW.class_id IS NOT OLD.class_id  OR NEW.plan_id IS NOT OLD.plan_id OR NEW.plan_version IS NOT OLD.plan_version OR NEW.amount IS NOT OLD.amount  OR NEW.monthly_limit IS NOT OLD.monthly_limit OR NEW.timezone IS NOT OLD.timezone OR NEW.connected_account IS NOT OLD.connected_account  OR NEW.connection_identity IS NOT OLD.connection_identity OR NEW.consent_version IS NOT OLD.consent_version  OR NEW.consented_at IS NOT OLD.consented_at OR NEW.request_key IS NOT OLD.request_key OR (NEW.request_json IS NOT OLD.request_json AND NOT ((EXISTS(SELECT 1 FROM line_accounts a WHERE a.id=OLD.account_id AND a.tenant_id=OLD.tenant_id AND a.data_purged_at IS NOT NULL) AND NEW."id" IS OLD."id" AND NEW."tenant_id" IS OLD."tenant_id" AND NEW."account_id" IS OLD."account_id" AND NEW."friend_id" IS OLD."friend_id" AND NEW."class_kind" IS OLD."class_kind" AND NEW."class_id" IS OLD."class_id" AND NEW."plan_id" IS OLD."plan_id" AND NEW."plan_version" IS OLD."plan_version" AND NEW."name" IS OLD."name" AND NEW."amount" IS OLD."amount" AND NEW."currency" IS OLD."currency" AND NEW."monthly_limit" IS OLD."monthly_limit" AND NEW."timezone" IS OLD."timezone" AND NEW."consent_version" IS OLD."consent_version" AND NEW."consented_at" IS OLD."consented_at" AND NEW."connected_account" IS OLD."connected_account" AND NEW."connection_identity" IS OLD."connection_identity" AND NEW."payment_method_id" IS OLD."payment_method_id" AND NEW."payment_method_version" IS OLD."payment_method_version" AND NEW."setup_session_id" IS OLD."setup_session_id" AND NEW."setup_expires_at" IS OLD."setup_expires_at" AND NEW."state" IS OLD."state" AND NEW."stop_reason" IS OLD."stop_reason" AND NEW."stop_effective_at" IS OLD."stop_effective_at" AND NEW."service_state" IS OLD."service_state" AND NEW."service_reason" IS OLD."service_reason" AND NEW."attention_episode_id" IS OLD."attention_episode_id" AND NEW."attention_started_at" IS OLD."attention_started_at" AND NEW."request_key" IS OLD."request_key" AND NEW."test_mode" IS OLD."test_mode" AND NEW."created_at" IS OLD."created_at") AND NEW.request_json = json_remove(OLD.request_json, '$.friendId')))  OR (OLD.customer_id IS NOT NULL AND NEW.customer_id IS NOT OLD.customer_id AND NOT ((EXISTS(SELECT 1 FROM line_accounts a WHERE a.id=OLD.account_id AND a.tenant_id=OLD.tenant_id AND a.data_purged_at IS NOT NULL) AND NEW."id" IS OLD."id" AND NEW."tenant_id" IS OLD."tenant_id" AND NEW."account_id" IS OLD."account_id" AND NEW."friend_id" IS OLD."friend_id" AND NEW."class_kind" IS OLD."class_kind" AND NEW."class_id" IS OLD."class_id" AND NEW."plan_id" IS OLD."plan_id" AND NEW."plan_version" IS OLD."plan_version" AND NEW."name" IS OLD."name" AND NEW."amount" IS OLD."amount" AND NEW."currency" IS OLD."currency" AND NEW."monthly_limit" IS OLD."monthly_limit" AND NEW."timezone" IS OLD."timezone" AND NEW."consent_version" IS OLD."consent_version" AND NEW."consented_at" IS OLD."consented_at" AND NEW."connected_account" IS OLD."connected_account" AND NEW."connection_identity" IS OLD."connection_identity" AND NEW."payment_method_id" IS OLD."payment_method_id" AND NEW."payment_method_version" IS OLD."payment_method_version" AND NEW."setup_session_id" IS OLD."setup_session_id" AND NEW."setup_expires_at" IS OLD."setup_expires_at" AND NEW."state" IS OLD."state" AND NEW."stop_reason" IS OLD."stop_reason" AND NEW."stop_effective_at" IS OLD."stop_effective_at" AND NEW."service_state" IS OLD."service_state" AND NEW."service_reason" IS OLD."service_reason" AND NEW."attention_episode_id" IS OLD."attention_episode_id" AND NEW."attention_started_at" IS OLD."attention_started_at" AND NEW."request_key" IS OLD."request_key" AND NEW."test_mode" IS OLD."test_mode" AND NEW."created_at" IS OLD."created_at") AND NEW.customer_id IS NULL))  OR NEW.version!=OLD.version+1  OR (OLD.state='expired' AND NEW.state!=OLD.state)  OR (OLD.state='stopped' AND NEW.state!=OLD.state AND NOT(NEW.state='active' AND OLD.stop_reason='unpaid'    AND NEW.stop_reason IS NULL AND NEW.stop_effective_at IS NULL AND EXISTS(SELECT 1 FROM booking_monthly_cycles y      WHERE y.contract_id=NEW.id AND y.state='paid' AND julianday(y.service_start)<=julianday('now') AND julianday(y.service_end)>julianday('now'))))  OR (OLD.state IN('active','stop_scheduled') AND NEW.state IN('applying','expired'))  OR (OLD.stop_reason IN('member_request','store_request','store_immediate') AND    (NEW.stop_reason IS NOT OLD.stop_reason AND NOT(NEW.stop_reason IS 'store_immediate' AND julianday(NEW.stop_effective_at)<=julianday(OLD.stop_effective_at))     OR NEW.stop_effective_at IS NULL OR julianday(NEW.stop_effective_at)>julianday(OLD.stop_effective_at)))  OR (NEW.state IN('active','stop_scheduled') AND NOT EXISTS(SELECT 1 FROM booking_monthly_active_slots s WHERE s.contract_id=NEW.id))  OR (OLD.state='applying' AND NEW.state IN('active','stop_scheduled') AND NOT EXISTS(SELECT 1 FROM booking_monthly_cycles y WHERE y.contract_id=NEW.id AND y.kind='initial' AND y.state='paid'))  OR (NEW.payment_method_id IS NOT OLD.payment_method_id AND NEW.payment_method_version!=OLD.payment_method_version+1)  OR (OLD.attention_started_at IS NOT NULL AND NEW.attention_started_at IS NOT NULL AND julianday(NEW.attention_started_at)>julianday(OLD.attention_started_at)) BEGIN SELECT RAISE(ABORT,'monthly_contract_conflict'); END;
